// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lucene;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The magic-property syntax of the set-returning extension functions must work on a {@link LuceneSail} stack in its
 * default (TRIPLE_SOURCE) evaluation mode, which runs its own optimizer list instead of the standard pipeline.
 */
public class LuceneSailMagicPropertyTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIXES = "PREFIX strf: <http://rdf4j.org/function/string#>\n"
			+ "PREFIX arrf: <http://rdf4j.org/function/array#>\n"
			+ "PREFIX search: <http://www.openrdf.org/contrib/lucenesail#>\n" + "PREFIX ex: <http://example.org/>\n";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		LuceneSail sail = new LuceneSail();
		sail.setParameter(LuceneSail.LUCENE_DIR_KEY, "lucene-index");
		sail.setParameter(LuceneSail.INDEX_CLASS_KEY, LuceneSail.DEFAULT_INDEX_CLASS);
		sail.setBaseSail(new MemoryStore());
		repository = new SailRepository(sail);
		repository.setDataDir(dataDir);
		repository.init();
		IRI tags = VF.createIRI("http://example.org/tags");
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(VF.createIRI("http://example.org/a"), tags, VF.createLiteral("red,blue"));
			conn.add(VF.createIRI("http://example.org/b"), tags, VF.createLiteral("green"));
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private List<String> column(String query, String name) {
		List<String> values = new ArrayList<>();
		try (SailRepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(PREFIXES + query).evaluate()) {
			for (BindingSet row : QueryResults.asList(result)) {
				values.add(row.getValue(name).stringValue());
			}
		}
		return values;
	}

	@Test
	void magicPropertiesAreRewrittenInTripleSourceMode() {
		assertThat(column("SELECT ?n WHERE { (1 3) arrf:generateSeries ?n } ORDER BY ?n", "n"))
				.containsExactly("1", "2", "3");
		assertThat(column("SELECT ?tag WHERE { ?s ex:tags ?tags . (?tags \",\") strf:split ?tag } ORDER BY ?tag",
				"tag")).containsExactly("blue", "green", "red");
	}

	@Test
	void luceneSearchStillWorksAlongsideMagicProperties() {
		assertThat(column("SELECT ?s ?n WHERE { ?s search:matches [ search:query \"green\" ] ."
				+ " (1 2) arrf:generateSeries ?n } ORDER BY ?n", "n")).containsExactly("1", "2");
	}
}
